    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '221: Which vaccine is specifically recommended for children traveling to the "Meningitis Belt" in sub-Saharan Africa?', '["MenACWY", "MenB", "Hib", "BCG"]', 0, 'MenACWY is crucial for travel to endemic areas. (Nelson)'),
    (v_topic_id, '222: At what age should a child "copy a cross"?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Cross = 4 years. (Harriet Lane)'),
    (v_topic_id, '223: Which of the following is the most effective way to prevent "dental caries" in children?', '["Regular brushing and fluoride", "Avoiding all fruit", "Drinking only milk", "None"]', 0, 'Fluoride and oral hygiene are primary prevention. (Nelson)'),
    (v_topic_id, '224: At what age should a child "balance on one foot for 2 seconds"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3 years = 2 seconds; 4 years = 5 seconds; 5 years = 10 seconds. (Nelson)'),
    (v_topic_id, '225: Which vaccine is given to prevent "Yellow Fever" for travel to certain tropical countries?', '["Yellow Fever vaccine", "Typhoid vaccine", "IPV", "MMR"]', 0, 'A live vaccine required for entry into some countries. (Harriet Lane)'),
    (v_topic_id, '226: A child has a "severe" allergy to "gelatin." Which vaccine should be avoided?', '["MMR and Varicella", "HepB", "PCV13", "DTaP"]', 0, 'Gelatin is used as a stabilizer in MMR and Varicella vaccines. (Nelson)'),
    (v_topic_id, '227: At what age should a child "ride a tricycle"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3 years = Tricycle. (Case Files)'),
    (v_topic_id, '228: Which of the following is the leading cause of "unintentional injury" death in adolescents?', '["Drowning", "Motor vehicle accidents (MVAs)", "Poisoning", "Falls"]', 1, 'MVAs are the #1 cause of death in the 15-19 age group. (CDC)'),
    (v_topic_id, '229: At what age should a child "copy a square"?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Square = 4-5 years. (Harriet Lane)'),
    (v_topic_id, '230: Which vaccine is given to prevent "Typhoid" for travel to endemic areas?', '["Typhoid vaccine (Oral or Injectable)", "HepA", "Cholera vaccine", "BCG"]', 0, 'Prevents infection with Salmonella Typhi. (Nelson)'),
    (v_topic_id, '231: A child has "nephrotic syndrome" and is on high-dose steroids. Can they receive the MMR vaccine today?', '["Yes", "No, wait until steroids are finished and immune system recovers", "Only the IM version", "Only after age 12"]', 1, 'High-dose steroids are an immunosuppressant contraindication to live vaccines. (Case Files)'),
    (v_topic_id, '232: At what age should a child "tell a story"?', '["2 years", "3 years", "4 years", "5 years"]', 2, '4-year-olds can describe connected events. (Nelson)'),
    (v_topic_id, '233: Which of the following is the most common cause of "fatal" child abuse?', '["Starvation", "Abdominal trauma", "Traumatic Brain Injury (Abusive Head Trauma)", "Poisoning"]', 2, 'Shaken baby syndrome/AHT is the leading cause of abuse death. (Nelson)'),
    (v_topic_id, '234: At what age should a child "draw a person with 3 parts"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4 years = 3 parts. (Harriet Lane)'),
    (v_topic_id, '235: Which vaccine is given to prevent "BCG" (Tuberculosis) in many developing countries?', '["BCG vaccine", "PPD", "QuantiFERON", "None"]', 0, 'BCG is a live-attenuated M. bovis vaccine. (Nelson)'),
    (v_topic_id, '236: A child who received the "BCG" vaccine may have a false positive on which test?', '["QuantiFERON", "PPD (Skin test)", "Chest X-ray", "Sputum culture"]', 1, 'The PPD test reacts to BCG; QuantiFERON is more specific for M. tuberculosis. (Case Files)'),
    (v_topic_id, '237: At what age should a child "hop on one foot"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4 years = Hopping. (Nelson)'),
    (v_topic_id, '238: Which of the following is the best way to prevent "sudden infant death syndrome (SIDS)"?', '["Avoid cigarette smoke", "Supine sleeping", "Breastfeeding", "All of the above"]', 3, 'Multiple factors reduce the risk. (Nelson)'),
    (v_topic_id, '239: At what age should a child "copy a triangle"?', '["4 years", "5 years", "6 years", "7 years"]', 1, 'Triangle = 5 years. (Harriet Lane)'),
    (v_topic_id, '240: Which vaccine is given to prevent "Japanese Encephalitis" for travel to certain parts of Asia?', '["JE vaccine", "Dengue vaccine", "Malaria pill", "Rabies vaccine"]', 0, 'Recommended for long-term travel to endemic rural areas. (Nelson)'),
    (v_topic_id, '241: A 12-month-old child is "exposed to Varicella" for the first time. They haven''t had the vaccine yet. What is the appropriate management?', '["Wait for symptoms", "Give the Varicella vaccine within 3-5 days of exposure", "Give Acyclovir now", "Give Varizig only"]', 1, 'Post-exposure vaccination can prevent or modify the disease. (CDC)'),
    (v_topic_id, '242: At what age should a child "tie their shoes"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '243: Which of the following is a "red flag" in an adolescent?', '["Wanting privacy", "Sudden drop in grades and withdrawal from social activities", "Sleeping late on weekends", "Wanting to spend time with friends"]', 1, 'Significant behavioral changes suggest depression or substance abuse. (Case Files)'),
    (v_topic_id, '244: At what age should a child "count 10 objects"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '245: Which vaccine is given to prevent "Rabies" after a high-risk animal bite?', '["Rabies vaccine (series) and HRIG", "Antibiotics only", "Tetanus only", "None"]', 0, 'Post-exposure prophylaxis (PEP) is vital. (Nelson)'),
    (v_topic_id, '246: A child is bitten by a "bat" while sleeping. Management?', '["Wait for symptoms", "Immediate PEP for Rabies", "Wash with soap only", "Check for fever"]', 1, 'Bat bites can be microscopic; exposure in a room while sleeping requires PEP. (Nelson)'),
    (v_topic_id, '247: At what age should a child "know their right and left"?', '["5 years", "6 years", "7 years", "8 years"]', 1, '6-year-old milestone. (Nelson)'),
    (v_topic_id, '248: Which of the following is the most common cause of "stridor" in a neonate?', '["Croup", "Laryngomalacia", "Epiglottitis", "Foreign body"]', 1, 'Congenital floppy airway is the most common cause of noisy breathing in infants. (Case Files)'),
    (v_topic_id, '249: At what age should a child "know the days of the week"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-6 year milestone. (Harriet Lane)'),
    (v_topic_id, '250: Which vaccine is given to prevent "cholera" for travel to areas with an active outbreak?', '["Oral cholera vaccine (Vaxchora)", "Typhoid vaccine", "HepA", "IPV"]', 0, 'Live-attenuated oral vaccine. (Nelson)'),
    (v_topic_id, '251: A child with "severe combined immunodeficiency (SCID)" should NEVER receive which vaccine?', '["HepB", "IPV", "Rotavirus (RV)", "PCV13"]', 2, 'RV is live and can cause disseminated infection in SCID infants. (Nelson)'),
    (v_topic_id, '252: At what age should a child "skip"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '253: Which of the following is the best way to prevent "iron deficiency" in a 6-month-old?', '["Giving them cow''s milk", "Introducing iron-fortified cereals and meats", "Giving them apple juice", "Only breastfeeding"]', 1, 'Introduction of iron-rich solids is key. (Case Files)'),
    (v_topic_id, '254: At what age should a child "draw a person with 6 parts"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '255: Which vaccine is associated with preventing "mumps-related" hearing loss?', '["MMR", "Varicella", "PCV13", "Hib"]', 0, 'Mumps can cause unilateral permanent sensorineural hearing loss. (Nelson)'),
    (v_topic_id, '256: A child has a "high fever" and a "strawberry tongue." This can be seen in which condition that has no vaccine?', '["Kawasaki Disease", "Measles", "Scarlet Fever", "Both A and C"]', 3, 'Kawasaki and Scarlet Fever both have strawberry tongues; neither has a vaccine. (Nelson)'),
    (v_topic_id, '257: At what age should a child "balance on one foot for 10 seconds"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '258: Which of the following is the most common cause of "preventable" intellectual disability?', '["Down Syndrome", "Fetal Alcohol Syndrome", "Congenital Hypothyroidism", "Lead poisoning"]', 2, 'Newborn screening and treatment prevents cretinism. (Case Files)'),
    (v_topic_id, '259: At what age should a child "ride a bicycle with training wheels"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '4-5 year milestone. (Harriet Lane)'),
    (v_topic_id, '260: Which vaccine is given to prevent "Dengue" in children aged 9-16 with laboratory-confirmed previous infection living in endemic areas?', '["Dengvaxia", "Yellow Fever", "JE vaccine", "None"]', 0, 'Dengue vaccine is only for those with prior infection. (CDC)'),
    (v_topic_id, '261: A child has "atopic dermatitis." Which "preventive" advice is most important?', '["Bathe only once a week", "Use thick emollients (e.g., Vaseline, Aquaphor) immediately after bathing", "Use scented soaps", "Avoid all baths"]', 1, 'Trapping moisture in the skin is the mainstay of eczema care. (Nelson)'),
    (v_topic_id, '262: At what age should a child "print some letters"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '263: Which of the following is the best way to prevent "lead poisoning" in the home?', '["Washing hands often", "Cleaning dust with a wet mop, and removing peeling lead paint", "Eating more sugar", "None"]', 1, 'Environmental control is primary. (Case Files)'),
    (v_topic_id, '264: At what age should a child "know their colors"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-4 year milestone. (Harriet Lane)'),
    (v_topic_id, '265: Which vaccine is given to prevent "meningitis" in college students living in dorms?', '["MenACWY", "MenB", "Hib", "Both A and B"]', 3, 'Dorms are high-risk environments for meningococcal outbreaks. (Nelson)'),
    (v_topic_id, '266: A child has "asthma." Which "preventive" test is used to monitor their lung function at home?', '["Pulse oximetry", "Peak Flow Meter", "Incentive spirometry", "X-ray"]', 1, 'Peak flow monitoring helps track daily control. (Nelson)'),
    (v_topic_id, '267: At what age should a child "catch a bounced ball"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4-year-old milestone. (Nelson)'),
    (v_topic_id, '268: Which of the following is the most common cause of "food-borne illness" in the US?', '["E. coli", "Salmonella", "Norovirus", "Listeria"]', 2, 'Norovirus is extremely common and highly contagious. (Case Files)'),
    (v_topic_id, '269: At what age should a child "dress themselves without help"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '270: Which vaccine is associated with preventing "congenital rubella" in the children of women vaccinated before pregnancy?', '["MMR", "Varicella", "DTaP", "HepB"]', 0, 'Rubella protection is a key goal of MMR. (Nelson)'),
    (v_topic_id, '271: A child has "sickle cell disease." Which "preventive" medication is given daily until age 5 to prevent sepsis?', '["Aspirin", "Penicillin VK", "Ibuprofen", "Vitamins"]', 1, 'Prophylactic penicillin significantly reduces mortality from S. pneumoniae. (Nelson)'),
    (v_topic_id, '272: At what age should a child "understand the difference between real and make-believe"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '273: Which of the following is the most common "accidental" cause of death in children <1 year?', '["Drowning", "Suffocation (usually sleep-related)", "MVAs", "Poisoning"]', 1, 'Safe sleep environments are vital. (Nelson)'),
    (v_topic_id, '274: At what age should a child "cut with scissors"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-4 year milestone. (Harriet Lane)'),
    (v_topic_id, '275: Which vaccine is associated with preventing "cervical dysplasia"?', '["MMR", "HepB", "HPV", "Varicella"]', 2, 'HPV vaccine prevents pre-cancerous lesions. (Nelson)'),
    (v_topic_id, '276: A child has "type 1 diabetes." Which "preventive" eye exam is needed annually starting 5 years after diagnosis?', '["Slit lamp for cataracts", "Dilated fundoscopic exam for retinopathy", "Vision screen only", "None"]', 1, 'Diabetic retinopathy screening starts after puberty or 5 years post-diagnosis. (Nelson)'),
    (v_topic_id, '277: At what age should a child "jump over a small object"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-year-old milestone. (Nelson)'),
    (v_topic_id, '278: Which of the following is the best way to prevent "firearm injuries" in a home?', '["Keeping the gun in a drawer", "Storing guns unloaded and locked, with ammunition locked separately", "Hiding the gun", "Teaching the child not to touch"]', 1, 'Safe storage is the only effective method. (AAP/Nelson)'),
    (v_topic_id, '279: At what age should a child "wash and dry their hands"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '280: Which vaccine is given to prevent "meningitis" in infants starting at 2 months?', '["MenACWY", "MenB", "Hib and PCV13", "MMR"]', 2, 'Hib and PCV13 are the main infant vaccines for meningitis. (Case Files)'),
    (v_topic_id, '281: A child has "cystic fibrosis." Which "preventive" treatment is used to clear mucus?', '["Chest physiotherapy", "Antibiotics", "Steroids", "Oxygen"]', 0, 'Airway clearance is a daily requirement. (Nelson)'),
    (v_topic_id, '282: At what age should a child "play board games or card games"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '283: Which of the following is the most common cause of "hearing loss" in school-age children?', '["Meningitis", "Chronic middle ear fluid (effusion)", "Genetic", "Noise exposure"]', 1, 'Conductive loss from fluid is very common. (Case Files)'),
    (v_topic_id, '284: At what age should a child "know their name and address"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '285: Which vaccine is associated with preventing "epiglottitis" and "septic arthritis" in infants?', '["Hib", "PCV13", "MMR", "IPV"]', 0, 'Hib was the #1 cause of both before vaccination. (Nelson)'),
    (v_topic_id, '286: A child has "recurrent" ear infections. Which "preventive" surgery might be considered?', '["Tonsillectomy", "Tympanostomy tube placement", "Adenoidectomy", "None"]', 1, 'Tubes help drain fluid and prevent infections. (Nelson)'),
    (v_topic_id, '287: At what age should a child "walk up stairs alternating feet"?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-year-old milestone. (Nelson)'),
    (v_topic_id, '288: Which of the following is the best way to prevent "skin cancer" in children?', '["Using sunscreen >SPF 30 and protective clothing", "Only staying inside", "Using tanning beds", "None"]', 0, 'Sun protection in childhood reduces lifetime risk. (Nelson)'),
    (v_topic_id, '289: At what age should a child "use a fork"?', '["12 months", "18 months", "2 years", "3 years"]', 1, '18-month milestone. (Harriet Lane)'),
    (v_topic_id, '290: Which vaccine is associated with preventing "acute rheumatic fever"?', '["None", "DTaP", "MMR", "PCV13"]', 0, 'There is no vaccine for Group A Strep, which causes rheumatic fever. (Nelson)'),
    (v_topic_id, '291: A child has a "high fever" and "barking cough" (Croup). Which "preventive" advice is most important for parents if it recurs?', '["Cool mist or steam", "Antibiotics", "Surgery", "None"]', 0, 'Supportive care is the mainstay of croup management. (Case Files)'),
    (v_topic_id, '292: At what age should a child "brush their teeth with help"?', '["As soon as teeth appear", "3 years", "5 years", "7 years"]', 0, 'Parents should brush for children until age 7-8. (Nelson)'),
    (v_topic_id, '293: Which of the following is the most common cause of "malaria" in travelers?', '["P. falciparum", "P. vivax", "P. ovale", "P. malariae"]', 0, 'Falciparum is the most severe and common. (Nelson)'),
    (v_topic_id, '294: At what age should a child "speak in 4-5 word sentences"?', '["2 years", "3 years", "4 years", "5 years"]', 2, '4-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '295: Which vaccine is associated with preventing "orchitis-induced infertility" in males?', '["MMR", "HepB", "HPV", "PCV13"]', 0, 'Mumps orchitis can lead to testicular atrophy. (Nelson)'),
    (v_topic_id, '296: A child has "asthma" triggered by "dust mites." Which "preventive" measure is best?', '["Using a HEPA filter", "Washing bedding in hot water and using dust-proof covers", "Getting a cat", "None"]', 1, 'Environmental control of allergens. (Nelson)'),
    (v_topic_id, '297: At what age should a child "know the difference between a nickel and a dime"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-6 year milestone. (Nelson)'),
    (v_topic_id, '298: Which of the following is the most common cause of "bronchiolitis" in infants?', '["Influenza", "RSV (Respiratory Syncytial Virus)", "Parainfluenza", "Adenovirus"]', 1, 'RSV is the #1 cause of infant wheezing. (Case Files)'),
    (v_topic_id, '299: Is there a vaccine for RSV?', '["No", "Yes, for all infants", "Nirsevimab (monoclonal antibody) is given for prevention", "Only for adults"]', 2, 'Nirsevimab is a long-acting antibody given to infants for RSV prevention. (CDC/Nelson)'),
    (v_topic_id, '300: At what age should a child "know their birthday"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4-5 year milestone. (Harriet Lane)'),
    (v_topic_id, '301: Which vaccine is given to prevent "tetanus, diphtheria, and pertussis" in a pregnant woman?', '["DTaP", "Tdap", "Td", "None"]', 1, 'Tdap is recommended in every pregnancy. (Nelson)'),
    (v_topic_id, '302: At what age should a child "play catch"?', '["2 years", "3 years", "4 years", "5 years"]', 2, '4-year-old milestone. (Nelson)'),
    (v_topic_id, '303: Which of the following is the most common "preventive" reason for a child to wear a "helmet"?', '["Playing soccer", "Biking, skating, and scootering", "Running", "Sleeping"]', 1, 'Prevents traumatic brain injury. (Nelson)'),
    (v_topic_id, '304: At what age should a child "name all colors correctly"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '305: Which vaccine is associated with preventing "chronic liver disease"?', '["HepA and HepB", "MMR", "Varicella", "PCV13"]', 0, 'Both Hep viruses cause liver damage. (Nelson)'),
    (v_topic_id, '306: A child has "atopy." Which "preventive" food advice is current?', '["Avoid peanuts until age 3", "Early introduction of peanuts (around 4-6 months) may prevent allergy", "Avoid all eggs", "None"]', 1, 'The LEAP study changed the guidance to early introduction. (Nelson)'),
    (v_topic_id, '307: At what age should a child "understand simple rules in a game"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4-year-old milestone. (Nelson)'),
    (v_topic_id, '308: Which of the following is the best way to prevent "head lice" spread?', '["Shaving the head", "Avoiding head-to-head contact and sharing hats/brushes", "Using pesticides on the rug", "None"]', 1, 'Lice crawl, they don''t fly or jump. (Case Files)'),
    (v_topic_id, '309: At what age should a child "know their phone number"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-6 year milestone. (Harriet Lane)'),
    (v_topic_id, '310: Which vaccine is given to prevent "meningitis" in travelers to the Middle East (Hajj/Umrah)?', '["MenACWY", "MenB", "Hib", "BCG"]', 0, 'Required for pilgrims to Saudi Arabia. (Nelson)'),
    (v_topic_id, '311: At what age should a child "be able to tell the difference between fantasy and reality"?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4-5 year milestone. (Nelson)'),
    (v_topic_id, '312: Which of the following is the best way to prevent "ticks" and "Lyme disease"?', '["Staying inside", "Wearing long pants tucked into socks and using DEET", "Eating garlic", "None"]', 1, 'Protective clothing and repellent. (Case Files)'),
    (v_topic_id, '313: At what age should a child "count to 20"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '314: Which vaccine is given to prevent "hand, foot, and mouth disease"?', '["None", "RV", "MMR", "Varicella"]', 0, 'Caused by Coxsackievirus; no vaccine currently available in the US. (Nelson)'),
    (v_topic_id, '315: At what age should a child "read some simple words"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '316: Which of the following is the most important "preventive" reason for a teenager to have a "yearly" well-check?', '["For shots only", "To screen for high-risk behaviors (HEADSS assessment)", "To check height", "None"]', 1, 'Psychosocial screening is the priority in adolescence. (Case Files)'),
    (v_topic_id, '317: At what age should a child "know the difference between penny, nickel, and dime"?', '["5 years", "6 years", "7 years", "8 years"]', 1, '6-year-old milestone. (Nelson)'),
    (v_topic_id, '318: Which vaccine is associated with preventing "blindness" caused by Measles in malnourished children?', '["MMR", "Vitamin A", "Both (MMR prevents, Vitamin A treats)", "None"]', 2, 'Vitamin A is critical for eye health during measles infection. (Nelson)'),
    (v_topic_id, '319: At what age should a child "be able to explain a simple rule"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '320: Which of the following is the most common cause of "preventable" blindness in children worldwide?', '["Glaucoma", "Trachoma", "Vitamin A deficiency", "Trauma"]', 2, 'Dietary deficiency remains a major global issue. (Nelson)'),
    (v_topic_id, '321: At what age should a child "hop 5 times on each foot"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '322: Which vaccine is given to prevent "rabies" before an exposure for travelers to high-risk areas?', '["PrEP (Pre-exposure prophylaxis)", "PEP", "HRIG", "None"]', 0, 'PrEP simplifies post-exposure care. (Nelson)'),
    (v_topic_id, '323: At what age should a child "be able to write their first name"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Nelson)'),
    (v_topic_id, '324: Which of the following is the best way to prevent "fire" injuries in the home?', '["Hiding matches", "Installing and testing smoke detectors", "Using candles", "None"]', 1, 'Active safety devices save lives. (Case Files)'),
    (v_topic_id, '325: At what age should a child "know their address"?', '["5 years", "6 years", "7 years", "8 years"]', 1, '6-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '326: Which vaccine is associated with preventing "whooping cough" in an infant when given to the mother?', '["Tdap", "DTaP", "MMR", "HepB"]', 0, 'Maternal Tdap provides passive immunity. (Nelson)'),
    (v_topic_id, '327: At what age should a child "be able to identify coins"?', '["5 years", "6 years", "7 years", "8 years"]', 1, '6-year-old milestone. (Nelson)'),
    (v_topic_id, '328: Which of the following is the best "preventive" advice for a child with "allergies" and a "pet dog"?', '["Keeping the dog out of the bedroom", "Giving the dog away", "Bathing the dog daily", "None"]', 0, 'Practical allergen reduction. (Nelson)'),
    (v_topic_id, '329: At what age should a child "be able to use a phone to call 911"?', '["4 years", "5 years", "6 years", "7 years"]', 1, '5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '330: Final Pearl: What is the single most important "preventive" intervention in pediatric history?', '["Antibiotics", "Immunizations", "Clean water", "The stethoscope"]', 1, 'Vaccines have saved more lives than any other medical intervention. (MediHelp Mastery)');
